+'use client';
+
+import { type ReactNode } from 'react';
+import {
+  Type,
+  Image as ImageIcon,
+  Video,
+  Hash,
+  List,
+  ToggleLeft
+} from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import {
+  Select,
+  SelectContent,
+  SelectItem,
+  SelectTrigger,
+  SelectValue
+} from '@/components/ui/select';
+import type { UiParameterField } from '@/components/ai-tool/parameter-field-utils';
+
+export const PARAMETER_SCHEMA_NS = 'admin.aiTools.parameterSchema';
+
+/** 資料類型選項（供 DataTypeSelect 與欄位編輯區共用） */
+export function useParameterSchemaSelectOptions() {
+  const t = useTranslations(PARAMETER_SCHEMA_NS);
+  const FIELD_TYPES: Array<{
+    value: UiParameterField['type'];
+    labelKey: string;
+    icon: ReactNode;
+  }> = [
+    {
+      value: 'text',
+      labelKey: t('textInput'),
+      icon: <Type className="h-4 w-4" />
+    },
+    {
+      value: 'image',
+      labelKey: t('imageUpload'),
+      icon: <ImageIcon className="h-4 w-4" />
+    },
+    {
+      value: 'video',
+      labelKey: t('videoUpload'),
+      icon: <Video className="h-4 w-4" />
+    },
+    {
+      value: 'number',
+      labelKey: t('numberInput'),
+      icon: <Hash className="h-4 w-4" />
+    },
+    {
+      value: 'select',
+      labelKey: t('selectField'),
+      icon: <List className="h-4 w-4" />
+    },
+    {
+      value: 'boolean',
+      labelKey: t('booleanField'),
+      icon: <ToggleLeft className="h-4 w-4" />
+    }
+  ];
+  return { FIELD_TYPES };
+}
+
+/** 資料類型選單（文字 / 圖片 / 影片 / 數字 / 下拉選單） */
+export function DataTypeSelect({
+  value,
+  onValueChange
+}: {
+  value: UiParameterField['type'];
+  onValueChange: (value: UiParameterField['type']) => void;
+}) {
+  const t = useTranslations(PARAMETER_SCHEMA_NS);
+  const { FIELD_TYPES } = useParameterSchemaSelectOptions();
+  return (
+    <Select
+      value={value}
+      onValueChange={(v) => onValueChange(v as UiParameterField['type'])}
+    >
+      <SelectTrigger className="w-[140px]">
+        <SelectValue placeholder={t('dataType')} />
+      </SelectTrigger>
+      <SelectContent>
+        {FIELD_TYPES.map((fieldType) => (
+          <SelectItem key={fieldType.value} value={fieldType.value}>
+            <div className="flex items-center gap-2">
+              {fieldType.icon}
+              <span>{fieldType.labelKey}</span>
+            </div>
+          </SelectItem>
+        ))}
+      </SelectContent>
+    </Select>
+  );
+}
